import Foundation

@main
struct ResourceEmbedder {
    static func main() throws {
        let arguments = CommandLine.arguments.dropFirst()
        guard let output = arguments.first else {
            fatalError("Usage: ResourceEmbedder <output.swift> <input>...")
        }
        
        var lines = [
            "// Generated by ResourceEmbedder. Do not edit.",
            "",
            "enum EmbeddedResources {"
        ]
        for path in arguments.dropFirst() {
            let url = URL(fileURLWithPath: path)
            let contents = try String(contentsOf: url, encoding: .utf8)
            let delimiter = rawStringDelimiter(for: contents)
            lines.append("    static let \(identifier(for: url.lastPathComponent)) = \(delimiter)\"\"\"")
            lines.append(contents)
            lines.append("\"\"\"\(delimiter)")
        }
        lines.append("}")
        
        try lines.joined(separator: "\n")
            .write(toFile: output, atomically: true, encoding: .utf8)
    }
    
    private static func identifier(for fileName: String) -> String {
        let words = fileName
            .split(whereSeparator: {!$0.isLetter && !$0.isNumber})
            .map(String.init)
        guard let first = words.first else {
            fatalError("Can't name a resource called '\(fileName)'")
        }
        return first.prefix(1).lowercased() + first.dropFirst()
            + words.dropFirst().map({$0.prefix(1).uppercased() + $0.dropFirst()}).joined()
    }
    
    private static func rawStringDelimiter(for contents: String) -> String {
        var longest = 0
        var current = 0
        var afterQuote = false
        for character in contents {
            if character == "#", afterQuote {
                current += 1
                longest = max(longest, current)
            } else {
                afterQuote = character == "\""
                current = 0
            }
        }
        return String(repeating: "#", count: longest + 1)
    }
}
